<script setup>
import { ref, computed } from 'vue'
import { X, Plus, Trash2, Check } from 'lucide-vue-next'
import { api } from '../recipeEditing'
const props=defineProps({catalog:Object})
const emit=defineEmits(['close','changed'])
const error=ref(''), groupName=ref(''), groupId=ref(''), tagName=ref(''), busy=ref(false)
const renamed=ref({})
const activeGroup=computed(()=>props.catalog.groups.find(g=>g.id===groupId.value)||props.catalog.groups[0])
async function act(path,method,body){busy.value=true;error.value='';try{await api(path,method,body);emit('changed');return true}catch(e){error.value=e.message;return false}finally{busy.value=false}}
async function addGroup(){if(await act('/tag-groups','POST',{name:groupName.value}))groupName.value=''}
async function addTag(){if(await act('/tags','POST',{group_id:activeGroup.value?.id,name:tagName.value}))tagName.value=''}
async function removeTag(tag){if(confirm('从所有食谱中移除标签“'+tag.name+'”？'))await act('/tags/'+tag.id,'DELETE')}
function removeGroup(group){const count=props.catalog.tags.filter(t=>t.group_id===group.id).length;if(count){error.value=`「${group.name}」还有 ${count} 个标签，请先在下方逐个删除，或把标签改名后归到其他分组，再删除本分组`;return}if(confirm('删除空分组“'+group.name+'”？'))act('/tag-groups/'+group.id,'DELETE')}
</script>
<template><div class="overlay tag-manager-overlay" @click.self="emit('close')"><section class="modal tag-manager"><button class="close" aria-label="关闭标签管理" @click="emit('close')"><X/></button><div class="eyebrow">ORGANIZE YOUR KITCHEN</div><h2>分组与标签</h2><p class="muted">名称由你定义。重命名后，关联食谱同步更新。</p><p v-if="error" role="alert" class="alert">{{error}}</p><h3>标签分组</h3><div v-for="group in catalog.groups" :key="group.id" class="registry-row"><input :value="renamed[group.id]??group.name" @input="renamed[group.id]=$event.target.value" :aria-label="'分组名称'+group.name" maxlength="80"/><button class="icon-button" :disabled="busy" :aria-label="'保存分组名称'+group.name" @click="act('/tag-groups/'+group.id,'PATCH',{name:renamed[group.id]??group.name})"><Check :size="17"/></button><button class="icon-button danger" :disabled="busy" :aria-label="'删除分组'+group.name" @click="removeGroup(group)"><Trash2 :size="16"/></button></div><form class="new-tag-row" @submit.prevent="addGroup"><input v-model="groupName" placeholder="例如：烹饪方式、适合谁吃" aria-label="新分组名称" maxlength="80" required/><button class="secondary" :disabled="busy"><Plus :size="15"/>新建分组</button></form><h3>分组内的标签</h3><select v-model="groupId" class="wide" aria-label="管理哪个分组"><option value="">{{catalog.groups[0]?.name||'请选择分组'}}</option><option v-for="group in catalog.groups" :value="group.id">{{group.name}}</option></select><div v-for="tag in catalog.tags.filter(t=>t.group_id===activeGroup?.id)" :key="tag.id" class="registry-row"><input :value="renamed[tag.id]??tag.name" @input="renamed[tag.id]=$event.target.value" :aria-label="'标签名称'+tag.name" maxlength="80"/><button class="icon-button" :disabled="busy" :aria-label="'保存标签名称'+tag.name" @click="act('/tags/'+tag.id,'PATCH',{name:renamed[tag.id]??tag.name})"><Check :size="17"/></button><button class="icon-button danger" :disabled="busy" :aria-label="'删除标签'+tag.name" @click="removeTag(tag)"><Trash2 :size="16"/></button></div><form v-if="activeGroup" class="new-tag-row" @submit.prevent="addTag"><input v-model="tagName" placeholder="自定义标签名称" aria-label="管理页新标签名称" maxlength="80" required/><button class="secondary" :disabled="busy"><Plus :size="15"/>新建标签</button></form></section></div></template>
